package io.knowledgebrain.planning;
import java.util.*;import java.time.*;import java.sql.Timestamp;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;import io.knowledgebrain.contracts.planning.goal.v1.*;
/** Planning owns goals, immutable revisions and their local transactional Outbox. */
final class GoalStore {
 record Input(String title,String description,String status,String targetDate){}
 record Goal(UUID goalId,UUID spaceId,String visibility,String state,long version,String title,String description,String status,String targetDate,String createdAt,String updatedAt){}
 record Creation(Goal goal,boolean replay){}
 record Summary(UUID goalId,String title,String status,String targetDate,long version,String updatedAt,String state){}
 record Page(UUID spaceId,String state,String status,List<Summary> items,UUID nextAfter){}
 record Revision(UUID revisionId,UUID goalId,long version,UUID actorId,String occurredAt,Goal snapshot){}
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 GoalStore(DataSource source,Clock clock){jdbc=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));tx.setTimeout(15);this.clock=clock;ids=new UuidV7(clock);}
 static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Goal unavailable");}
 private String hash(Input input){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(input)));}catch(Exception e){throw new IllegalStateException(e);}}
 Creation create(UUID space,UUID actor,String key,Input input,String trace){GoalRules.id(space);GoalRules.id(actor);GoalRules.trace(trace);GoalRules.input(input);if(key==null||!key.matches("[0-9a-f]{32}"))throw GoalRules.bad();String hash=hash(input);return tx.execute(s->{var id=ids.next();var now=clock.instant();int inserted=jdbc.update("INSERT INTO goal(goal_id,space_id,visibility,state,version,title,description,status,target_date,created_at,updated_at,request_key,request_hash) VALUES (?,?,'PRIVATE','ACTIVE',1,?,?,?,?,?,?,?,?) ON CONFLICT(space_id,request_key) DO NOTHING",id,space,input.title(),input.description(),input.status(),input.targetDate()==null?null:LocalDate.parse(input.targetDate()),Timestamp.from(now),Timestamp.from(now),key,hash);if(inserted==0){var rows=jdbc.query("SELECT g.request_hash,r.snapshot::text FROM goal g JOIN goal_revision r ON r.goal_id=g.goal_id AND r.version=1 WHERE g.space_id=? AND g.request_key=?",(rs,n)->Map.entry(rs.getString(1),rs.getString(2)),space,key);if(rows.size()!=1)throw new IllegalStateException("Original goal creation missing");if(!MessageDigest.isEqual(hash.getBytes(StandardCharsets.US_ASCII),rows.getFirst().getKey().getBytes(StandardCharsets.US_ASCII)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Creation key already represents different goal input");return new Creation(json.readValue(rows.getFirst().getValue(),Goal.class),true);}var value=new Goal(id,space,"PRIVATE","ACTIVE",1,input.title(),input.description(),input.status(),input.targetDate(),now.toString(),now.toString());revision(value,actor,trace,"GoalCreated");return new Creation(value,false);});}
 private Goal decode(String raw,UUID space,UUID id,long version,String state){if(raw==null)throw new IllegalStateException("Goal revision missing");var value=json.readValue(raw,Goal.class);if(!value.spaceId().equals(space)||!value.goalId().equals(id)||value.version()!=version||!value.state().equals(state)||!value.visibility().equals("PRIVATE"))throw new IllegalStateException("Goal revision mismatch");return value;}
 private Goal current(UUID space,UUID id,boolean lock,boolean active){GoalRules.id(space);GoalRules.id(id);if(lock){record Head(long version,String state){}var heads=jdbc.query("SELECT version,state FROM goal WHERE space_id=? AND goal_id=? FOR UPDATE",(rs,n)->new Head(rs.getLong(1),rs.getString(2)),space,id);if(heads.isEmpty()||active&&!heads.getFirst().state().equals("ACTIVE"))throw missing();var h=heads.getFirst();String raw=jdbc.queryForObject("SELECT snapshot::text FROM goal_revision WHERE goal_id=? AND version=?",String.class,id,h.version());return decode(raw,space,id,h.version(),h.state());}var rows=jdbc.query("SELECT g.version,g.state,r.snapshot::text FROM goal g LEFT JOIN goal_revision r ON r.goal_id=g.goal_id AND r.version=g.version WHERE g.space_id=? AND g.goal_id=?",(rs,n)->decode(rs.getString(3),space,id,rs.getLong(1),rs.getString(2)),space,id);if(rows.isEmpty()||active&&!rows.getFirst().state().equals("ACTIVE"))throw missing();return rows.getFirst();}
 Goal get(UUID space,UUID id){return current(space,id,false,true);}
 Goal change(UUID space,UUID id,UUID actor,long expected,Input input,boolean retire,String trace){GoalRules.id(actor);GoalRules.trace(trace);if(expected<1)throw GoalRules.bad();if(!retire)GoalRules.input(input);return tx.execute(s->{var prior=current(space,id,true,true);if(prior.version()!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Goal changed; inspect latest before saving");if(!retire&&new Input(prior.title(),prior.description(),prior.status(),prior.targetDate()).equals(input))return prior;var value=new Goal(id,space,"PRIVATE",retire?"RETIRED":"ACTIVE",Math.addExact(prior.version(),1),retire?prior.title():input.title(),retire?prior.description():input.description(),retire?prior.status():input.status(),retire?prior.targetDate():input.targetDate(),prior.createdAt(),clock.instant().toString());jdbc.update("UPDATE goal SET title=?,description=?,status=?,target_date=?,state=?,version=?,updated_at=? WHERE goal_id=?",value.title(),value.description(),value.status(),value.targetDate()==null?null:LocalDate.parse(value.targetDate()),value.state(),value.version(),Timestamp.from(Instant.parse(value.updatedAt())),id);revision(value,actor,trace,retire?"GoalRetired":"GoalUpdated");return value;});}
 Page list(UUID space,String status,UUID after,int limit){return list(space,"ACTIVE",status,after,limit);}
 Page list(UUID space,String state,String status,UUID after,int limit){GoalRules.id(space);if(after!=null)GoalRules.id(after);if(!Set.of("ACTIVE","RETIRED").contains(state)||status==null||!status.equals("ALL")&&!GoalRules.STATUSES.contains(status)||limit<1||limit>100)throw GoalRules.bad();var args=new ArrayList<Object>();args.add(space);args.add(state);String sql="SELECT goal_id,title,status,target_date,version,updated_at,state FROM goal WHERE space_id=? AND state=?";if(!status.equals("ALL")){sql+=" AND status=?";args.add(status);}if(after!=null){sql+=" AND goal_id>?";args.add(after);}sql+=" ORDER BY goal_id LIMIT ?";args.add(limit+1);var rows=jdbc.query(sql,(rs,n)->new Summary(rs.getObject(1,UUID.class),rs.getString(2),rs.getString(3),rs.getObject(4,LocalDate.class)==null?null:rs.getObject(4,LocalDate.class).toString(),rs.getLong(5),rs.getTimestamp(6).toInstant().toString(),rs.getString(7)),args.toArray());var page=List.copyOf(rows.subList(0,Math.min(rows.size(),limit)));return new Page(space,state,status,page,rows.size()>limit?page.getLast().goalId():null);}
 List<Revision> history(UUID space,UUID id,long before,int limit){current(space,id,false,false);if(before<1||limit<1||limit>10)throw GoalRules.bad();return jdbc.query("SELECT revision_id,goal_id,version,actor_id,occurred_at,snapshot::text FROM goal_revision WHERE goal_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getLong(3),rs.getObject(4,UUID.class),rs.getTimestamp(5).toInstant().toString(),json.readValue(rs.getString(6),Goal.class)),id,before,limit);}
 private void revision(Goal value,UUID actor,String trace,String type){UUID revision=ids.next(),event=ids.next();var now=Instant.parse(value.updatedAt());jdbc.update("INSERT INTO goal_revision VALUES (?,?,?,?,?,?::jsonb)",revision,value.goalId(),value.version(),actor,Timestamp.from(now),json.writeValueAsString(value));var payload=GoalChangedPayloadV1.newBuilder().setGoalId(value.goalId().toString()).setRevisionId(revision.toString()).setVersion(value.version()).setVisibility("PRIVATE").setState(value.state()).setTitle(value.title()).setDescription(value.description()).setStatus(value.status()).setTargetDate(value.targetDate()==null?"":value.targetDate()).setCreatedAt(value.createdAt()).setUpdatedAt(value.updatedAt()).build();var envelope=GoalEventEnvelopeV1.newBuilder().setEventId(event.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("planning-service").setAggregateType("Goal").setAggregateId(value.goalId().toString()).setSpaceId(value.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(payload.toByteString()).build();jdbc.update("INSERT INTO outbox_event VALUES (?,'goal',?,?,?,?, 'planning','goal-events','1',?)",event,value.goalId(),type,Timestamp.from(now),trace,envelope.toByteArray());}
}
